import React, { useState, useRef, useEffect } from 'react';
const [isTyping, setIsTyping] = useState(false);


function App() {
  const [userInput, setUserInput] = useState('');
  const [messages, setMessages] = useState([]);
  const messagesEndRef = useRef(null);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const sendMessage = async () => {
    if (!userInput.trim()) return;

    const newMessages = [...messages, { type: 'user', text: userInput }];
    setMessages(newMessages);
    setUserInput('');

    try {
      setIsTyping(true);
      const response = await fetch('https://hook.eu2.make.com/fci7oybacyp9pytg3hg1irh8dtlzq5b9', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ message: userInput }),
      });

      const data = await response.json();
      setMessages([...newMessages, { type: 'bot', text: data.reply }]);
    } catch (error) {
      setMessages([...newMessages, { type: 'bot', text: 'Feil ved henting av svar.' }]);
      setMessages((prev) => [...prev, { type: 'bot', text: data.reply }]);
    }
    setIsTyping(false);
  };

  return (
    <div className="max-w-2xl mx-auto mt-10 p-4 border border-gray-300 rounded-xl shadow-md bg-white h-[90vh] flex flex-col">
      <h1 className="text-2xl font-bold text-center mb-6 mt-3">🤖 AI-Chatbot for Nor Klinikken Madla</h1>
      <div className="flex-1 overflow-y-auto px-2 space-y-3">
        {messages.map((msg, index) => (
          <div
            key={index}
            className={ "max-w-[80%] p-3 rounded-lg whitespace-pre-wrap break-words " + (msg.type === 'user' ? 'border black-400 bg-blue-600 text-white self-end ml-auto shadow-sm' : 'border black-400 bg-gray-100 text-gray-900 self-start mr-auto shadow-sm') }          >
            {msg.text}
            {isTyping && (
              <div className="self-start bg-gray-100 text-gray-700 px-4 py-2 rounded-lg border border-gray-300 mb-2">
                <span className="typing-dots">
                  <span className="dot dot1">.</span>
                  <span className="dot dot2">.</span>
                            <span className="dot dot3">.</span>
                    </span>
              </div>
          )}
          </div>




        ))}
        <div ref={messagesEndRef} />
      </div>
      <div className="mt-4 flex gap-2">
        <input
          type="text"
          value={userInput}
          onChange={(e) => setUserInput(e.target.value)}
          onKeyDown={(e) => e.key === 'Enter' && sendMessage()}
          placeholder="Skriv et spørsmål..."
          className="flex-1 p-3 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-400"
        />
        <button
          onClick={sendMessage}
          className="bg-blue-600 text-white px-4 py-2 rounded-md hover:bg-blue-700 transition"
        >
          Send
        </button>
      </div>
    </div>
  );
}

export default App;
